#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NAME_SIZE 64
#define PHONE_SIZE 25

struct Contact {
    int id;
    char name[NAME_SIZE];
    char phone[PHONE_SIZE];
};

struct ContactBook {
    struct Contact *items;
    size_t count;
    size_t capacity;
};

static int valid_contact(const struct Contact *contact) {
    size_t i;
    size_t name_length;
    size_t phone_length;
    size_t digit_count = 0U;
    if (contact == NULL || contact->id <= 0) return 0;
    name_length = strlen(contact->name);
    phone_length = strlen(contact->phone);
    if (name_length == 0U || name_length >= NAME_SIZE || phone_length >= PHONE_SIZE) return 0;
    for (i = 0; i < phone_length; ++i) {
        if (i == 0U && contact->phone[i] == '+') continue;
        if (contact->phone[i] < '0' || contact->phone[i] > '9') return 0;
        ++digit_count;
    }
    if (digit_count < 7U || digit_count > 23U) return 0;
    return 1;
}

static int reserve_contacts(struct ContactBook *book, size_t needed) {
    size_t new_capacity;
    struct Contact *new_items;
    if (book == NULL) return 0;
    if (needed <= book->capacity) return 1;
    if (needed > SIZE_MAX / sizeof *book->items) return 0;
    new_capacity = book->capacity == 0U ? 2U : book->capacity;
    while (new_capacity < needed) {
        if (new_capacity > SIZE_MAX / 2U) {
            new_capacity = needed;
            break;
        }
        new_capacity *= 2U;
    }
    if (new_capacity > SIZE_MAX / sizeof *book->items) return 0;
    new_items = realloc(book->items, new_capacity * sizeof *book->items);
    if (new_items == NULL) return 0;
    book->items = new_items;
    book->capacity = new_capacity;
    return 1;
}

static size_t find_contact(const struct ContactBook *book, int id) {
    size_t i;
    if (book == NULL) return 0U;
    for (i = 0; i < book->count; ++i)
        if (book->items[i].id == id) return i;
    return book->count;
}

static int add_contact(struct ContactBook *book, const struct Contact *contact) {
    if (book == NULL || !valid_contact(contact)) return 0;
    if (find_contact(book, contact->id) != book->count) return 0;
    if (book->count == SIZE_MAX || !reserve_contacts(book, book->count + 1U)) return 0;
    book->items[book->count] = *contact;
    ++book->count;
    return 1;
}

static int update_phone(struct ContactBook *book, int id, const char *phone) {
    size_t index;
    struct Contact candidate;
    if (book == NULL || phone == NULL) return 0;
    index = find_contact(book, id);
    if (index == book->count) return 0;
    candidate = book->items[index];
    if (strlen(phone) >= PHONE_SIZE) return 0;
    (void)snprintf(candidate.phone, sizeof candidate.phone, "%s", phone);
    if (!valid_contact(&candidate)) return 0;
    book->items[index] = candidate;
    return 1;
}

static int delete_contact(struct ContactBook *book, int id) {
    size_t index;
    size_t i;
    if (book == NULL) return 0;
    index = find_contact(book, id);
    if (index == book->count) return 0;
    for (i = index; i + 1U < book->count; ++i)
        book->items[i] = book->items[i + 1U];
    --book->count;
    return 1;
}

static void destroy_book(struct ContactBook *book) {
    if (book == NULL) return;
    free(book->items);
    book->items = NULL;
    book->count = 0U;
    book->capacity = 0U;
}

int main(void) {
    struct ContactBook book = { NULL, 0U, 0U };
    const struct Contact a = { 1, "Asha Rao", "+919876543210" };
    const struct Contact b = { 2, "Ravi Kumar", "9876543210" };
    const struct Contact c = { 3, "Mina Das", "9123456789" };
    const struct Contact duplicate = { 2, "Duplicate", "9000000000" };
    const struct Contact invalid = { 4, "Bad Phone", "12AB" };

    assert(add_contact(&book, &a));
    assert(book.count == 1U && book.capacity >= 1U);
    assert(add_contact(&book, &b));
    assert(book.capacity >= 2U);
    assert(add_contact(&book, &c));
    assert(book.capacity >= 3U);
    assert(!add_contact(&book, &duplicate));
    assert(!add_contact(&book, &invalid));
    assert(find_contact(&book, 2) == 1U);
    assert(find_contact(&book, 99) == book.count);
    assert(update_phone(&book, 2, "+911234567890"));
    assert(strcmp(book.items[1].phone, "+911234567890") == 0);
    assert(!update_phone(&book, 2, "bad-number"));
    assert(!update_phone(&book, 99, "9123456789"));
    assert(delete_contact(&book, 1));
    assert(book.count == 2U && book.items[0].id == 2);
    assert(!delete_contact(&book, 99));
    destroy_book(&book);
    assert(book.items == NULL && book.count == 0U && book.capacity == 0U);
    puts("Dynamic contact book tests passed.");
    return 0;
}

#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NAME_SIZE 64
#define PHONE_SIZE 25
#define LINE_SIZE 128

struct Contact {
    int id;
    char name[NAME_SIZE];
    char phone[PHONE_SIZE];
};

struct ContactBook {
    struct Contact *items;
    size_t count;
    size_t capacity;
};

enum ReadResult { READ_OK, READ_END, READ_INVALID };

static enum ReadResult read_line(const char *prompt, char *buffer, size_t size) {
    size_t length;
    int ch;
    fputs(prompt, stdout);
    if (fgets(buffer, (int)size, stdin) == NULL) return READ_END;
    length = strlen(buffer);
    if (length > 0U && buffer[length - 1U] == '\n') {
        buffer[length - 1U] = '\0';
        return READ_OK;
    }
    ch = getchar();
    if (ch == '\n' || ch == EOF) return READ_OK;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return READ_INVALID;
}

static char *trim(char *text) {
    char *start = text;
    char *end;
    while (isspace((unsigned char)*start)) ++start;
    end = start + strlen(start);
    while (end > start && isspace((unsigned char)end[-1])) --end;
    *end = '\0';
    return start;
}

static int read_integer(const char *prompt, int *value) {
    char line[LINE_SIZE];
    char *start;
    char *end;
    long parsed;
    enum ReadResult result = read_line(prompt, line, sizeof line);
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    start = trim(line);
    errno = 0;
    parsed = strtol(start, &end, 10);
    while (isspace((unsigned char)*end)) ++end;
    if (start == end || *end != '\0' || errno == ERANGE
        || parsed < 1L || parsed > (long)INT_MAX) return -1;
    *value = (int)parsed;
    return 1;
}

static int read_text(const char *prompt, char *destination, size_t capacity) {
    char line[LINE_SIZE];
    char *clean;
    size_t length;
    enum ReadResult result = read_line(prompt, line, sizeof line);
    if (result != READ_OK) return result == READ_END ? 0 : -1;
    clean = trim(line);
    length = strlen(clean);
    if (length == 0U || length >= capacity) return -1;
    memcpy(destination, clean, length + 1U);
    return 1;
}

static int valid_phone(const char *phone) {
    size_t i;
    size_t length;
    size_t digit_count = 0U;
    if (phone == NULL) return 0;
    length = strlen(phone);
    if (length == 0U || length >= PHONE_SIZE) return 0;
    for (i = 0; i < length; ++i) {
        if (i == 0U && phone[i] == '+') continue;
        if (phone[i] < '0' || phone[i] > '9') return 0;
        ++digit_count;
    }
    return digit_count >= 7U && digit_count <= 23U;
}

static size_t find_contact(const struct ContactBook *book, int id) {
    size_t i;
    for (i = 0; i < book->count; ++i)
        if (book->items[i].id == id) return i;
    return book->count;
}

static int reserve_contacts(struct ContactBook *book, size_t needed) {
    size_t new_capacity;
    struct Contact *new_items;
    if (needed <= book->capacity) return 1;
    if (needed > SIZE_MAX / sizeof *book->items) return 0;
    new_capacity = book->capacity == 0U ? 2U : book->capacity;
    while (new_capacity < needed) {
        if (new_capacity > SIZE_MAX / 2U) {
            new_capacity = needed;
            break;
        }
        new_capacity *= 2U;
    }
    if (new_capacity > SIZE_MAX / sizeof *book->items) return 0;
    new_items = realloc(book->items, new_capacity * sizeof *book->items);
    if (new_items == NULL) return 0;
    book->items = new_items;
    book->capacity = new_capacity;
    return 1;
}

static void add_contact(struct ContactBook *book) {
    struct Contact item;
    int status;
    if (book->count == SIZE_MAX || !reserve_contacts(book, book->count + 1U)) {
        puts("Memory allocation failed; no contact was added.");
        return;
    }
    status = read_integer("Contact ID (positive integer): ", &item.id);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid ID."); return; }
    if (find_contact(book, item.id) != book->count) {
        puts("That ID already exists.");
        return;
    }
    status = read_text("Name: ", item.name, sizeof item.name);
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid or overlong name."); return; }
    status = read_text("Phone (7-23 digits, optional leading +): ", item.phone, sizeof item.phone);
    if (status != 1 || !valid_phone(item.phone)) {
        puts(status == 0 ? "Input ended." : "Invalid phone number.");
        return;
    }
    book->items[book->count] = item;
    ++book->count;
    puts("Contact added.");
}

static void list_contacts(const struct ContactBook *book) {
    size_t i;
    if (book->count == 0U) { puts("No contacts."); return; }
    puts("\nID       NAME                                     PHONE");
    for (i = 0; i < book->count; ++i)
        printf("%-8d %-40s %s\n", book->items[i].id,
               book->items[i].name, book->items[i].phone);
}

static void search_contact(const struct ContactBook *book) {
    int id;
    int status = read_integer("ID to search: ", &id);
    size_t index;
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid ID."); return; }
    index = find_contact(book, id);
    if (index == book->count) puts("Contact not found.");
    else printf("Found: %d | %s | %s\n", book->items[index].id,
                book->items[index].name, book->items[index].phone);
}

static void update_contact(struct ContactBook *book) {
    int id;
    int status = read_integer("ID to update: ", &id);
    size_t index;
    char phone[PHONE_SIZE];
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid ID."); return; }
    index = find_contact(book, id);
    if (index == book->count) { puts("Contact not found."); return; }
    status = read_text("New phone: ", phone, sizeof phone);
    if (status != 1 || !valid_phone(phone)) {
        puts(status == 0 ? "Input ended." : "Invalid phone number.");
        return;
    }
    (void)snprintf(book->items[index].phone, sizeof book->items[index].phone, "%s", phone);
    puts("Contact updated.");
}

static void delete_contact(struct ContactBook *book) {
    int id;
    int status = read_integer("ID to delete: ", &id);
    size_t index;
    size_t i;
    if (status != 1) { puts(status == 0 ? "Input ended." : "Invalid ID."); return; }
    index = find_contact(book, id);
    if (index == book->count) { puts("Contact not found."); return; }
    for (i = index; i + 1U < book->count; ++i)
        book->items[i] = book->items[i + 1U];
    --book->count;
    puts("Contact deleted.");
}

int main(void) {
    struct ContactBook book = { NULL, 0U, 0U };
    for (;;) {
        char line[LINE_SIZE];
        char *start;
        char *end;
        long choice;
        enum ReadResult status;
        puts("\nDYNAMIC CONTACT BOOK");
        puts("1 Add  2 List  3 Search  4 Update phone  5 Delete  0 Exit");
        status = read_line("Choose: ", line, sizeof line);
        if (status == READ_END) { puts("\nEnd of input."); break; }
        if (status != READ_OK) { puts("Menu line too long."); continue; }
        start = trim(line);
        errno = 0;
        choice = strtol(start, &end, 10);
        while (isspace((unsigned char)*end)) ++end;
        if (start == end || *end != '\0' || errno == ERANGE
            || choice < 0L || choice > 5L) {
            puts("Choose a number from 0 to 5.");
            continue;
        }
        switch (choice) {
            case 1: add_contact(&book); break;
            case 2: list_contacts(&book); break;
            case 3: search_contact(&book); break;
            case 4: update_contact(&book); break;
            case 5: delete_contact(&book); break;
            case 0: goto finished;
            default: break;
        }
    }
finished:
    free(book.items);
    book.items = NULL;
    book.count = 0U;
    book.capacity = 0U;
    puts("Contact book memory released. Goodbye.");
    return 0;
}
